extends RefCounted

# Archetype-based Entity Component System
# Entity handle = (generation << 32) | index

# State
var _generations: Array = []       # index: slot, value: current generation
var _freed_slots: Array = []       # stack of available slot indices
var _entity_archetypes: Array = [] # index: slot, value: archetype key (sorted Array of StringName)
var _entity_components: Array = [] # index: slot, value: Dictionary {type: data}
var _next_slot: int = 0            # used to assign brand new slots

const _INDEX_BITS = 32
const _INDEX_MASK = (1 << 32) - 1

func _is_slot_alive(slot: int, generation: int) -> bool:
	return slot >= 0 && slot < _generations.size() && _generations[slot] == generation

func get_index(entity: int) -> int:
	return entity & _INDEX_MASK

func get_generation(entity: int) -> int:
	return entity >> _INDEX_BITS

func is_alive(entity: int) -> bool:
	return _is_slot_alive(get_index(entity), get_generation(entity))

func _make_handle(slot: int, generation: int) -> int:
	return (generation << _INDEX_BITS) | slot

func create_entity() -> int:
	var slot: int
	var generation: int
	if _freed_slots.size() > 0:
		slot = _freed_slots.pop_back()
		_generations[slot] += 1
		generation = _generations[slot]
	else:
		slot = _next_slot
		_next_slot += 1
		_generations.append(1)
		generation = 1

	# Ensure state arrays are large enough
	while _entity_archetypes.size() <= slot:
		_entity_archetypes.append(null)
		_entity_components.append(null)

	_entity_archetypes[slot] = []
	_entity_components[slot] = {}
	return _make_handle(slot, generation)

func destroy_entity(entity: int) -> bool:
	var index = get_index(entity)
	var gen = get_generation(entity)
	if not _is_slot_alive(index, gen):
		return false

	_entity_archetypes[index] = null
	_entity_components[index] = null
	_freed_slots.append(index)
	return true

func _get_archetype_key(types: Array) -> Array:
	var sorted = types.duplicate()
	sorted.sort()
	return sorted

func _migrate(slot: int, new_types: Array) -> void:
	_entity_archetypes[slot] = _get_archetype_key(new_types)

func add_component(entity: int, component_type: StringName, data: Dictionary) -> bool:
	var index = get_index(entity)
	var gen = get_generation(entity)
	if not _is_slot_alive(index, gen):
		return false

	var types = _entity_archetypes[index]
	if not types.has(component_type):
		var new_types = types.duplicate()
		new_types.append(component_type)
		_migrate(index, new_types)

	_entity_components[index][component_type] = data
	return true

func remove_component(entity: int, component_type: StringName) -> bool:
	var index = get_index(entity)
	var gen = get_generation(entity)
	if not _is_slot_alive(index, gen):
		return false

	var types = _entity_archetypes[index]
	if not types.has(component_type):
		return false

	var new_types = []
	for t in types:
		if t != component_type:
			new_types.append(t)

	_entity_components[index].erase(component_type)
	_migrate(index, new_types)
	return true

func has_component(entity: int, component_type: StringName) -> bool:
	if not is_alive(entity):
		return false
	return _entity_archetypes[get_index(entity)].has(component_type)

func get_component(entity: int, component_type: StringName) -> Variant:
	if not is_alive(entity):
		return null
	return _entity_components[get_index(entity)].get(component_type, null)

func get_component_types(entity: int) -> Variant:
	if not is_alive(entity):
		return null
	return _entity_archetypes[get_index(entity)].duplicate()

func query(required_types: Array) -> Array:
	var result = []
	var req_set = {}
	for t in required_types:
		req_set[t] = true

	# Iterate all slots; since we reuse indices and generations track liveness,
	# we must check is_alive for every slot.
	for i in range(_next_slot):
		if _is_slot_alive(i, _generations[i]):
			var types = _entity_archetypes[i]
			var ok = true
			for rt in req_set:
				if not types.has(rt):
					ok = false
					break
			if ok:
				result.append(_make_handle(i, _generations[i]))
	return result

func get_entities_with_exact_types(types: Array) -> Array:
	var result = []
	var target = _get_archetype_key(types)
	for i in range(_next_slot):
		if _is_slot_alive(i, _generations[i]):
			if _entity_archetypes[i] == target:
				result.append(_make_handle(i, _generations[i]))
	return result

